<script>
  // This is the Svelte twin of packages/astro/components/SVG/Noise.astro.
  // Same component, same props, same output — one for each framework. Keep them in sync.

  import { noiseColorMatrix } from '@splendidlabz/utils'

  let {
    class: klass = '',
    frequency = 0.9,
    strength = 0.1,
    blend = 'overlay',
    color = 'rainbow',
  } = $props()

  // frequency — how zoomed in the noise is.
  //   low  (0.01–0.1): large blobs, clouds, smoke
  //   high (0.5–1):    fine grain, film noise, static

  // color — 'rainbow' (default) for coloured static. A preset name
  // ('black', 'sepia', 'synthwave') or any hex for a single-colour tint.

  // strength — 0–1 fades the grain; above 1 it saturates into denser grain.
  // Need the whole overlay dimmer? Add CSS opacity via class.
  const matrix = $derived(noiseColorMatrix(color, strength))

  const svg = $derived(
    "<svg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'>" +
      "<filter id='n'>" +
      `<feTurbulence type='fractalNoise' baseFrequency='${frequency}' numOctaves='2' stitchTiles='stitch'/>` +
      `<feColorMatrix values='${matrix}'/>` +
      '</filter>' +
      "<rect width='100%' height='100%' filter='url(%23n)'/>" +
      '</svg>',
  )

  const bg = $derived(`url("data:image/svg+xml;utf8,${svg}")`)
</script>

<div
  style:background-image={bg}
  style:mix-blend-mode={blend}
  class="Noise {klass}"
  aria-hidden="true"
></div>

<style>
  .Noise {
    position: absolute;
    inset: 0;
    pointer-events: none;
  }
</style>
